def main():
    output_dir = Path("C:/Users/Dean/anesthesia_attending/data")
    output_file = output_dir / "phase2_copd_asthma_chunks.json"
    output_dir.mkdir(parents=True, exist_ok=True)

    for idx, unit in enumerate(PHASE2_COPD_ASTHMA_UNITS):
        unit["id"] = f"phase2_copd_asthma_unit_{idx}"
        if "library" not in unit:
            unit["library"] = "intern_year_medicine"
        unit["created_at"] = datetime.now().isoformat()

    with open(output_file, "w") as f:
        for unit in PHASE2_COPD_ASTHMA_UNITS:
            f.write(json.dumps(unit) + "\n")

    print(f"Generated {len(PHASE2_COPD_ASTHMA_UNITS)} COPD/asthma knowledge units")
    return len(PHASE2_COPD_ASTHMA_UNITS)

if __name__ == "__main__":
    main()
